public final class MainActivity extends Activity {
 static boolean foreground=false;
 private static final String ORIGIN="https://bookwiz.local";
 private static final int SAVE=41,UPLOAD=42,OPEN_BACKUP=43;
 private final android.util.LruCache<String,byte[]> assetCache=new android.util.LruCache<String,byte[]>(24*1024*1024){@Override protected int sizeOf(String key,byte[] value){return value.length;}};
 private WebView web; private ValueCallback<Uri[]> upload;
 private String pendingReminders,pendingSession; private boolean pendingNotificationTest=false; private ReadAloud readAloud;
 private byte[] exportBytes; private WebView printView; private boolean deliveringWidget=false,studioReady=false;
 private final String bridge="document.documentElement.style.setProperty('--safe-top','0px');document.documentElement.style.setProperty('--safe-bottom','0px');window.__bookwizSpeechRequests={};window.__bookwizSpeechReply=function(id,value,error){var p=window.__bookwizSpeechRequests[id];if(!p)return;delete window.__bookwizSpeechRequests[id];error?p.reject(new Error(error)):p.resolve(value);};window.__bookwizSpeechCall=function(action,payload){return new Promise(function(resolve,reject){var id='speech-'+Date.now()+'-'+Math.random();window.__bookwizSpeechRequests[id]={resolve:resolve,reject:reject};BookWizAndroid.speech(action,id,JSON.stringify(payload||{}));setTimeout(function(){window.__bookwizSpeechReply(id,null,'The speech engine did not respond. Try another voice.');},action==='voices'?10000:300000);});};window.BookWizHost=Object.freeze({speechVoices:function(){return window.__bookwizSpeechCall('voices');},speakText:function(p){return window.__bookwizSpeechCall('speak',p);},pauseSpeech:function(){BookWizAndroid.speech('pause','','{}');},resumeSpeech:function(){BookWizAndroid.speech('resume','','{}');},stopSpeech:function(){BookWizAndroid.speech('stop','','{}');},platform:'android',widgetReady:function(){BookWizAndroid.widgetReady();},openClock:function(){BookWizAndroid.openClock();},openBackup:function(){BookWizAndroid.openBackup();},managesKeyboardInsets:"+(Build.VERSION.SDK_INT>=30)+",scheduleReminders:function(p){BookWizAndroid.scheduleReminders(JSON.stringify(p));},testNotification:function(){BookWizAndroid.testNotification();},scheduleSession:function(p){BookWizAndroid.scheduleSession(JSON.stringify(p));},openSettings:function(){BookWizAndroid.openSettings();},updateWidgets:function(p){BookWizAndroid.updateWidgets(JSON.stringify(p));},setTheme:function(p){BookWizAndroid.setTheme(JSON.stringify(p));},saveFile:function(p){BookWizAndroid.saveFile(p.name,p.base64,p.mime);},printHTML:function(html,options){BookWizAndroid.printHTML(html,JSON.stringify(options||{}));}});";
 @Override public void onCreate(Bundle state){if((getResources().getConfiguration().uiMode & android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES)setTheme(R.style.BookWizThemeDark);super.onCreate(state);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(23,24,28));web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);
  WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setUseWideViewPort(true);s.setLoadWithOverviewMode(false);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(true);s.setJavaScriptCanOpenWindowsAutomatically(false);if(Build.VERSION.SDK_INT>=26)s.setSafeBrowsingEnabled(true);
  WebView.setWebContentsDebuggingEnabled(false);web.addJavascriptInterface(new Host(),"BookWizAndroid");
  web.setWebViewClient(new WebViewClient(){
   @Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){studioReady=false;}
   @Override public void onPageFinished(WebView view,String url){deliverWidgetAction();}
   @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri u=request.getUrl();if(!u.getScheme().equals("https")||!u.getHost().equals("bookwiz.local"))return null;String path=u.getPath();if(path==null||path.equals("/"))path="/index.html";if(path.contains(".."))return response("text/plain",404,new ByteArrayInputStream(new byte[0]));try{byte[] cached=assetCache.get(path);if(cached==null){cached=readAll(getAssets().open("web"+path));assetCache.put(path,cached);}InputStream input=new ByteArrayInputStream(cached);if(path.equals("/index.html")){String html=new String(readAll(input),"UTF-8");html=html.replace("<head>","<head><script>"+bridge+"</script>");input=new ByteArrayInputStream(html.getBytes("UTF-8"));}return response(mime(path),200,input);}catch(Exception e){return response("text/plain",404,new ByteArrayInputStream(new byte[0]));}}
   @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(url.startsWith(ORIGIN+"/"))return false;if(request.hasGesture())openExternal(url);return true;}
   @Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setTitle("Open BookWiz").setMessage("The local studio could not open. Your saved work remains on this device.").setPositiveButton("Try again",(d,w)->web.loadUrl(ORIGIN+"/index.html")).show();}
  });
  web.setWebChromeClient(new WebChromeClient(){
   @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(upload!=null)upload.onReceiveValue(null);upload=callback;try{startActivityForResult(params.createIntent(),UPLOAD);return true;}catch(Exception e){upload=null;return false;}}
   @Override public boolean onCreateWindow(WebView view,boolean dialog,boolean gesture,android.os.Message result){if(!gesture)return false;WebView popup=new WebView(MainActivity.this);popup.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){openExternal(r.getUrl().toString());v.destroy();return true;}});((WebView.WebViewTransport)result.obj).setWebView(popup);result.sendToTarget();return true;}
  });
  if(Build.VERSION.SDK_INT>=30){root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());android.graphics.Insets ime=insets.getInsets(WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));web.evaluateJavascript("document.documentElement.toggleAttribute('data-keyboard-open',"+insets.isVisible(WindowInsets.Type.ime())+")",null);return insets;});}
  if(state!=null)web.restoreState(state);else web.loadUrl(ORIGIN+"/index.html");if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->handleDeviceBack());
 }
 private WebResourceResponse response(String type,int status,InputStream input){Map<String,String> headers=new HashMap<>();headers.put("Cache-Control","no-store");return new WebResourceResponse(type,type.startsWith("text/")||type.contains("javascript")?"UTF-8":null,status,status==200?"OK":"Not found",headers,input);}
 private static byte[] readAll(InputStream in)throws IOException{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 private static String mime(String p){if(p.endsWith(".html"))return "text/html";if(p.endsWith(".js")||p.endsWith(".mjs"))return "application/javascript";if(p.endsWith(".css"))return "text/css";if(p.endsWith(".svg"))return "image/svg+xml";if(p.endsWith(".png"))return "image/png";if(p.endsWith(".ttf"))return "font/ttf";if(p.endsWith(".wasm"))return "application/wasm";if(p.endsWith(".json")||p.endsWith(".webmanifest"))return "application/json";return "application/octet-stream";}
 private void openExternal(String url){try{Uri u=Uri.parse(url);boolean wallet="bitcoin".equals(u.getScheme())&&("bitcoin:36QW21MQQxUK7ohBQnvP5itipe4bFx91Bo".equals(url)||"bitcoin:36QW21MQQxUK7ohBQnvP5itipe4bFx91Bo?label=BookWiz".equals(url));if(wallet||"https".equals(u.getScheme())||"mailto".equals(u.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){error("This link could not open. For Bitcoin support, install a compatible wallet or copy the address.");}}
 private void error(String text){runOnUiThread(()->web.evaluateJavascript("window.dispatchEvent(new CustomEvent('bookwiz-native-error',{detail:"+JSONObject.quote(text)+"}))",null));}
 private void deliverWidgetAction(){
  if(web==null||!studioReady||deliveringWidget)return;final Intent pending=getIntent();String action=pending.getStringExtra("bookwiz-widget");if(action==null)return;
  try{JSONObject detail=new JSONObject();detail.put("action",action);detail.put("projectId",pending.getStringExtra("bookwiz-project"));detail.put("chapterId",pending.getStringExtra("bookwiz-chapter"));deliveringWidget=true;
   web.evaluateJavascript("(function(){if(!window.BookWizWidgetReady)return false;window.dispatchEvent(new CustomEvent('bookwiz-widget-action',{detail:"+detail+"}));return true;})()",result->{deliveringWidget=false;if("true".equals(result)&&getIntent()==pending){pending.removeExtra("bookwiz-widget");pending.removeExtra("bookwiz-project");pending.removeExtra("bookwiz-chapter");}if(getIntent()!=pending)deliverWidgetAction();});
  }catch(Exception e){deliveringWidget=false;error("This shortcut could not open. Open BookWiz and choose the page again.");}
 }
 private void reminderStatus(String status,boolean enabled){web.evaluateJavascript("window.dispatchEvent(new CustomEvent('bookwiz-reminder-status',{detail:{status:"+JSONObject.quote(status)+",enabled:"+enabled+"}}))",null);}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){
  super.onRequestPermissionsResult(request,permissions,results);if(request!=91)return;
  if(pendingReminders!=null){try{if(WritingReminders.allowed(this)){WritingReminders.apply(this,pendingReminders);reminderStatus("granted",true);}else{WritingReminders.apply(this,"{}");reminderStatus("denied",false);}}catch(Exception e){reminderStatus("error",false);}pendingReminders=null;}
  if(pendingSession!=null){try{WritingReminders.session(this,new JSONObject(pendingSession));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)error("Your timer is running. Enable notifications in device Settings for a session-finished alert.");}catch(Exception e){error("The session notification could not be scheduled.");}pendingSession=null;}
  if(pendingNotificationTest){pendingNotificationTest=false;showTestNotification();}
 }
 private void showTestNotification(){boolean sent=WritingReminders.test(this);web.evaluateJavascript("window.dispatchEvent(new CustomEvent('bookwiz-notification-test',{detail:{sent:"+sent+"}}))",null);}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(web!=null)deliverWidgetAction();}
 private void speechReply(String id,Object value,String error){runOnUiThread(()->{if(web==null||isDestroyed())return;String json=value==null?"null":value.toString();web.evaluateJavascript("window.__bookwizSpeechReply("+JSONObject.quote(id)+","+json+","+(error==null?"null":JSONObject.quote(error))+")",null);});}
 private final class Host {
  @JavascriptInterface public void speech(String action,String id,String payload){runOnUiThread(()->{if(readAloud==null)readAloud=new ReadAloud(MainActivity.this,(request,value,error)->speechReply(request,value,error));try{switch(action){case "voices":readAloud.voices(id);break;case "speak":readAloud.speak(id,new JSONObject(payload));break;case "pause":readAloud.pause();break;case "resume":readAloud.resume();break;case "stop":readAloud.stop();break;}}catch(Exception e){speechReply(id,null,"The speech engine could not complete this request.");}});}

  @JavascriptInterface public void scheduleReminders(String json){runOnUiThread(()->{try{JSONObject p=new JSONObject(json);if(!p.optBoolean("enabled")){WritingReminders.apply(MainActivity.this,json);reminderStatus("granted",false);return;}if(WritingReminders.allowed(MainActivity.this)){WritingReminders.apply(MainActivity.this,json);reminderStatus("granted",true);}else if(p.optBoolean("requestPermission")&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingReminders=json;requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},91);}else{WritingReminders.apply(MainActivity.this,"{}");reminderStatus("denied",false);}}catch(Exception e){reminderStatus("error",false);}});}
  @JavascriptInterface public void testNotification(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingNotificationTest=true;requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},91);}else showTestNotification();});}
  @JavascriptInterface public void scheduleSession(String json){runOnUiThread(()->{try{JSONObject p=new JSONObject(json);if(p.optBoolean("enabled")&&p.optBoolean("requestPermission")&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingSession=json;requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},91);}else WritingReminders.session(MainActivity.this,p);}catch(Exception e){error("The session notification could not be scheduled.");}});}
  @JavascriptInterface public void openBackup(){runOnUiThread(()->{try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/json","text/plain","application/octet-stream"});startActivityForResult(intent,OPEN_BACKUP);}catch(Exception e){error("The file picker could not open.");}});}
  @JavascriptInterface public void openSettings(){runOnUiThread(()->{try{startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}catch(Exception e){Toast.makeText(MainActivity.this,"Open BookWiz in your device Settings.",Toast.LENGTH_LONG).show();}});}
  @JavascriptInterface public void updateWidgets(String json){try{if(json==null||json.length()>16000)return;JSONObject safe=BookWidgets.safeSnapshot(new JSONObject(json));getSharedPreferences("bookwiz-widgets",0).edit().putString("data",safe.toString()).apply();BookWidgets.refresh(MainActivity.this);}catch(Exception ignored){}}
  @JavascriptInterface public void widgetReady(){runOnUiThread(()->{studioReady=true;deliverWidgetAction();});}
  @JavascriptInterface public void openClock(){runOnUiThread(()->{try{startActivity(new Intent(android.provider.AlarmClock.ACTION_SHOW_ALARMS));}catch(Exception e){error("No clock app is available. Install or enable your device’s Clock app to open alarms.");}});}

  @JavascriptInterface public void setTheme(String json){try{JSONObject p=new JSONObject(json);String hex=p.getString("background");if(!hex.matches("#[0-9a-fA-F]{6}"))return;final int color=Color.parseColor(hex);final boolean dark=p.optBoolean("dark",true);runOnUiThread(()->{web.setBackgroundColor(color);if(web.getParent() instanceof View)((View)web.getParent()).setBackgroundColor(color);getWindow().setStatusBarColor(color);getWindow().setNavigationBarColor(color);if(Build.VERSION.SDK_INT>=30){WindowInsetsController controller=getWindow().getInsetsController();if(controller!=null){int mask=WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS;controller.setSystemBarsAppearance(dark?0:mask,mask);}}else{int mask=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;int flags=getWindow().getDecorView().getSystemUiVisibility();getWindow().getDecorView().setSystemUiVisibility(dark?flags&~mask:flags|mask);}});}catch(Exception ignored){}}

  @JavascriptInterface public void saveFile(String name,String base64,String mime){if(base64==null||base64.length()>90000000){error("The export is too large.");return;}runOnUiThread(()->{if(exportBytes!=null){error("Finish the current save first.");return;}try{exportBytes=Base64.decode(base64,Base64.DEFAULT);Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(mime==null?"application/octet-stream":mime);intent.putExtra(Intent.EXTRA_TITLE,name.replaceAll("[\\\\/<>:\"|?*]","_"));startActivityForResult(intent,SAVE);}catch(Exception e){exportBytes=null;error("The save dialog could not open.");}});}
  @JavascriptInterface public void printHTML(String html,String optionsJSON){
   if(html==null||html.length()>20000000){error("This manuscript is too large to print.");return;}
   final JSONObject options;try{options=new JSONObject(optionsJSON);}catch(Exception e){error("The print settings could not be read.");return;}
   final double width=options.optDouble("width",5.5),height=options.optDouble("height",8.5);
   if(!Double.isFinite(width)||!Double.isFinite(height)||width<3||width>14||height<3||height>14){error("Choose a book size between 3 and 14 inches before printing.");return;}
   runOnUiThread(()->{try{
    if(printView!=null)printView.destroy();printView=new WebView(MainActivity.this);printView.getSettings().setJavaScriptEnabled(true);printView.getSettings().setTextZoom(100);printView.getSettings().setUseWideViewPort(false);printView.getSettings().setLoadWithOverviewMode(false);
    final PrintAttributes attributes=new PrintAttributes.Builder().setMediaSize(new PrintAttributes.MediaSize("BOOKWIZ_TRIM","BookWiz "+width+" × "+height+" in",(int)Math.round(width*1000),(int)Math.round(height*1000))).setMinMargins(PrintAttributes.Margins.NO_MARGINS).setResolution(new PrintAttributes.Resolution("BOOKWIZ_PDF","BookWiz PDF",300,300)).setColorMode(PrintAttributes.COLOR_MODE_COLOR).build();
    printView.setWebViewClient(new WebViewClient(){private boolean opened=false;@Override public void onPageFinished(WebView v,String url){if(opened||isFinishing()||isDestroyed())return;opened=true;try{PrintManager manager=(PrintManager)getSystemService(PRINT_SERVICE);if(manager==null)throw new IllegalStateException();manager.print("BookWiz manuscript",new BookPrintAdapter(v,options.optDouble("margin",.7)),attributes);}catch(Exception e){error("The print sheet could not open. Enable your device’s print service and try again.");}}});
    printView.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);
   }catch(Exception e){error("The native PDF view could not open. Your manuscript is still saved.");}});
  }
 }
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==OPEN_BACKUP&&result==RESULT_OK&&data!=null&&data.getData()!=null)readBackup(data.getData());if(code==UPLOAD&&upload!=null){upload.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));upload=null;}if(code==SAVE){if(result==RESULT_OK&&data!=null&&exportBytes!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(exportBytes);}catch(Exception e){error("The export could not be saved. Your book is still on this device.");}}exportBytes=null;}}
 @Override protected void onResume(){super.onResume();foreground=true;WritingReminders.refresh(this);}
 @Override protected void onPause(){foreground=false;super.onPause();}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
 private void readBackup(Uri uri){new Thread(()->{try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException();ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){if(bytes.size()+n>30*1024*1024)throw new IOException();bytes.write(buffer,0,n);}String text=new String(bytes.toByteArray(),"UTF-8");runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())web.evaluateJavascript("window.dispatchEvent(new CustomEvent('bookwiz-open-backup',{detail:{text:"+JSONObject.quote(text)+"}}))",null);});}catch(Exception error){error("The backup could not be opened. Choose a BookWiz JSON file under 30 MB.");}},"BookWiz-backup").start();}
 private void handleDeviceBack(){if(web==null){finish();return;}web.evaluateJavascript("window.BookWizDeviceBack ? window.BookWizDeviceBack() : false",result->{if(!"true".equals(result))finish();});}
 @Override public void onBackPressed(){handleDeviceBack();}
 @Override protected void onDestroy(){if(readAloud!=null)readAloud.destroy();if(upload!=null)upload.onReceiveValue(null);if(printView!=null)printView.destroy();if(web!=null){web.removeJavascriptInterface("BookWizAndroid");web.destroy();}super.onDestroy();}
}
